-- R1 EXPAND: additive only. Old code is unaffected.
ALTER TABLE claims ADD COLUMN payer_ref TEXT;
CREATE INDEX CONCURRENTLY idx_claims_payer_ref ON claims (payer_ref);

-- R2 code writes BOTH columns, still reads the old one.

-- R2b BACKFILL in batches. Never one statement over 10M rows: it holds
-- locks, bloats WAL, and blows up replication lag.
UPDATE claims SET payer_ref = payer_id
 WHERE payer_ref IS NULL AND id BETWEEN :lo AND :hi;

-- R3 code reads the NEW column, still writes both (rollback stays safe).

-- R4 CONTRACT: only once nothing reads or writes the old column.
ALTER TABLE claims DROP COLUMN payer_id;
